g=[[7]*8 for _ in range(21)]
marks={0:[3],1:[5],3:[2,7],4:[3,6],8:[0,2,5],9:[2,4,5],14:[5],16:[3],18:[6],19:[4],20:[2]}
for r,cs in marks.items():
 for c in cs:g[r][c]=8
# fill row gaps
for r in range(21):
 cs=[c for c,v in enumerate(g[r]) if v==8]
 if len(cs)>1:
  for c in range(min(cs)+1,max(cs)):
   if g[r][c]==7:g[r][c]=3
# fill col gaps
for c in range(8):
 rs=[r for r in range(21) if g[r][c]==8]
 if len(rs)>1:
  for r in range(min(rs)+1,max(rs)):
   if g[r][c]==7:g[r][c]=3
print(g)
